This program makes each folder and then reports how many of the three it had to create:
import java.io.File;
import java.io.IOException;
import java.util.Scanner;
public class DirManifest {
    static void clear(File root) {
        File[] kids = root.listFiles();
        if (kids != null) { for (File k : kids) { clear(k); } }
        root.delete();
    }
    public static void main(String[] args) throws IOException {
        clear(new File("reports"));
        clear(new File("archive"));
        Scanner sc = new Scanner(new File("folders.txt"));
        int made = 0;
        int depth = 0;
        while (sc.hasNextLine()) {
            String p = sc.nextLine().trim();
            if (p.isEmpty()) { continue; }
            if (new File(p).mkdirs()) { made++; }
            depth += p.split("/").length;
        }
        sc.close();
        System.out.println(made + "|" + depth);
    }
}
How many folders does the program create?

