import java.io.File;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;
public class WritePerFolder {
    static void clear(File root) {
        File[] kids = root.listFiles();
        if (kids != null) { for (File k : kids) { clear(k); } }
        root.delete();
    }
    public static void main(String[] args) throws IOException {
        clear(new File("out"));
        Scanner sc = new Scanner(new File("jobs.txt"));
        int files = 0;
        int bytes = 0;
        while (sc.hasNextLine()) {
            String p = sc.nextLine().trim();
            if (p.isEmpty()) { continue; }
            File full = new File(p);
            File dir = full.getParentFile();
            dir.mkdirs();
            String name = full.getName();
            try (PrintWriter w = new PrintWriter(new File(dir, name + ".txt"))) {
                w.print("x");
            }
            files++;
            bytes += new File(dir, name + ".txt").length();
        }
        sc.close();
        System.out.println(files + "|" + bytes);
    }
