        Scanner sc = new Scanner(new File("dupes.txt"));
        int writes = 0;
        Set<String> seen = new LinkedHashSet<>();
        while (sc.hasNextLine()) {
            String p = sc.nextLine().trim();
            if (p.isEmpty()) { continue; }
            File full = new File(p);
            full.getParentFile().mkdirs();
            String name = full.getName() + ".txt";
            try (PrintWriter w = new PrintWriter(new File(full.getParentFile(), name))) {
                w.print("x");
            }
            writes++;
            seen.add(name);
        }
        sc.close();
        System.out.println(writes + "|" + seen.size());
    }
}
